from solution import parse_nested_parens
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def ref_depth(group: str) -> int:
    d = 0
    m = 0
    for c in group:
        if c == "(":
            d += 1
            if d > m:
                m = d
        else:
            d -= 1
    return m


def ref(paren_string: str):
    # groups are non-empty whitespace separated tokens
    return [ref_depth(g) for g in paren_string.split() if g]


balanced_atom = st.one_of(
    st.just("()"),
    st.integers(min_value=1, max_value=4).map(lambda n: "(" * n + ")" * n),
    st.integers(min_value=1, max_value=4).map(lambda n: "()" * n),
    st.sampled_from(["(())", "(()())", "((()))", "((())()())", "()()", "(())()", "(()(()))", "()(()())"]),
)

groups_strategy = st.lists(balanced_atom, min_size=0, max_size=5)


# explicit spec example
def test_spec_example():
    assert parse_nested_parens('(()()) ((())) () ((())()())') == [2, 3, 1, 3]


def test_empty_string():
    assert parse_nested_parens('') == []


def test_single_simple_group():
    assert parse_nested_parens('()') == [1]


def test_single_nested_group():
    assert parse_nested_parens('((()))') == [3]
    assert parse_nested_parens('(()())') == [2]


def test_spaces_only_yield_no_groups():
    assert parse_nested_parens(' ') == []
    assert parse_nested_parens('   ') == []


def test_leading_trailing_spaces_ignored():
    assert parse_nested_parens(' (()()) ') == [2]
    assert parse_nested_parens('  ()  ') == [1]


def test_multiple_spaces_do_not_create_groups():
    assert parse_nested_parens('()  ()') == [1, 1]
    assert parse_nested_parens('(()())  ((()))') == [2, 3]


def test_deep_nesting_chain():
    assert parse_nested_parens('(' * 1 + ')' * 1) == [1]
    assert parse_nested_parens('(' * 2 + ')' * 2) == [2]
    assert parse_nested_parens('(' * 3 + ')' * 3) == [3]
    assert parse_nested_parens('(' * 5 + ')' * 5) == [5]


def test_flat_repetition_depth_one():
    assert parse_nested_parens('()()') == [1]
    assert parse_nested_parens('()()()') == [1]
    assert parse_nested_parens('() () ()') == [1, 1, 1]


@given(groups_strategy)
def test_property_length_equals_number_of_groups(groups):
    s = " ".join(groups)
    res = parse_nested_parens(s)
    assert res == ref(s)
    assert len(res) == len(groups)


@given(groups_strategy)
def test_property_equivalence_to_reference(groups):
    s = " ".join(groups)
    assert parse_nested_parens(s) == [ref_depth(g) for g in groups]


@given(groups_strategy)
def test_property_depth_bounds(groups):
    s = " ".join(groups)
    res = parse_nested_parens(s)
    for g, d in zip(groups, res):
        assert 1 <= d <= len(g) // 2 if len(g) > 0 else True
        assert d <= len(g)
        # max depth cannot exceed number of opens
        assert d <= g.count("(")


@given(groups_strategy)
def test_property_extra_spaces_ignored(groups):
    if len(groups) == 0:
        assume(False)
    # join with varying spaces + leading/trailing
    base = " ".join(groups)
    padded = "  " + "   ".join(groups) + " "
    assert parse_nested_parens(padded) == parse_nested_parens(base) == ref(base)


@given(st.lists(balanced_atom, min_size=1, max_size=3))
def test_property_nesting_increases_depth_by_one(groups):
    # "(" + g + ")" should have depth ref_depth(g)+1
    for g in groups:
        assume(len(g) > 0)
        nested = "(" + g + ")"
        # single group string
        assert parse_nested_parens(nested) == [ref_depth(g) + 1]
    # in context of a list: wrap first group
    wrapped = ["(" + groups[0] + ")"] + groups[1:]
    s_orig = " ".join(groups)
    s_wrap = " ".join(wrapped)
    r_orig = parse_nested_parens(s_orig)
    r_wrap = parse_nested_parens(s_wrap)
    assert r_wrap[0] == r_orig[0] + 1
    assert r_wrap[1:] == r_orig[1:]


@given(balanced_atom, balanced_atom)
def test_property_concatenation_max(a, b):
    # depth of concatenation a+b (no space, still balanced) is max of depths
    concat = a + b
    assert parse_nested_parens(concat) == [max(ref_depth(a), ref_depth(b))]
    # with space they are separate groups
    spaced = a + " " + b
    assert parse_nested_parens(spaced) == [ref_depth(a), ref_depth(b)]


@given(st.integers(min_value=1, max_value=6))
def test_property_pure_nesting_chain(n):
    s = "(" * n + ")" * n
    assert parse_nested_parens(s) == [n]


@given(st.integers(min_value=1, max_value=6))
def test_property_flat_chain_depth_one(n):
    s = "()" * n
    assert parse_nested_parens(s) == [1]


@given(groups_strategy)
def test_property_order_preserved(groups):
    s = " ".join(groups)
    res = parse_nested_parens(s)
    # reversing input reverses output
    s_rev = " ".join(reversed(groups))
    res_rev = parse_nested_parens(s_rev)
    assert res_rev == list(reversed(res))
